        for ((index, btn) in buttons.withIndex()) {
            val y = startY + index * itemHeight
            if (y + itemHeight > height - 40) break

            guiGraphics.fill(centerX - 150, y, centerX + 150, y + 24, 0x70000000)

            // Иконка предмета
            val item = btn.getItem()
            guiGraphics.renderItem(item, centerX - 140, y + 4)

            // Текстовые данные
            val cmdDisplay = if ((btn.command ?: "").length > 18) (btn.command ?: "").take(15) + "..." else (btn.command ?: "")
            val tipDisplay = if ((btn.tooltip ?: "").length > 15) (btn.tooltip ?: "").take(12) + "..." else (btn.tooltip ?: "")
            guiGraphics.drawString(font, "§e${btn.icon}", centerX - 115, y + 7, -1)
            guiGraphics.drawString(font, "§f$cmdDisplay", centerX - 40, y + 7, -1)
            guiGraphics.drawString(font, "§8$tipDisplay", centerX + 30, y + 7, -1)

            // Кнопки управления
            val btnSize = 16
            val upY = y + 4
            val downY = y + 4
            val delY = y + 4

            // Вверх
            if (index > 0) {
                val upX = centerX + 100
                guiGraphics.fill(upX, upY, upX + btnSize, upY + btnSize, 0x55000000)
                guiGraphics.drawCenteredString(font, "▲", upX + btnSize / 2, upY + 4, if (isHover(mouseX, mouseY, upX, upY, btnSize, btnSize)) -1 else 0xFFAAAAAA.toInt())
            }
            // Вниз
            if (index < buttons.size - 1) {
                val downX = centerX + 118
                guiGraphics.fill(downX, downY, downX + btnSize, downY + btnSize, 0x55000000)
                guiGraphics.drawCenteredString(font, "▼", downX + btnSize / 2, downY + 4, if (isHover(mouseX, mouseY, downX, downY, btnSize, btnSize)) -1 else 0xFFAAAAAA.toInt())
            }
            // Удалить
            val delX = centerX + 136
            guiGraphics.fill(delX, delY, delX + btnSize, delY + btnSize, 0x55000000)
            guiGraphics.drawCenteredString(font, "✕", delX + btnSize / 2, delY + 4, if (isHover(mouseX, mouseY, delX, delY, btnSize, btnSize)) 0xFFFF5555.toInt() else 0xFFAAAAAA.toInt())
        }

        if (buttons.isEmpty()) {
            guiGraphics.drawCenteredString(font, "§7Нет кнопок. Добавьте первую!", width / 2, startY + 20, 0xFFAAAAAA.toInt())
        }

        guiGraphics.drawCenteredString(font, "§7ESC - Назад", width / 2, height - 20, 0xFFAAAAAA.toInt())
    }

    private fun isHover(mx: Int, my: Int, x: Int, y: Int, w: Int, h: Int): Boolean {
        return mx.toDouble() in x.toDouble()..(x + w).toDouble() && my.toDouble() in y.toDouble()..(y + h).toDouble()
    }

    override fun mouseClicked(event: MouseButtonEvent, isDoubleClick: Boolean): Boolean {
        val mouseX = event.x()
        val mouseY = event.y()
        val button = event.button()

        if (button != 0) return super.mouseClicked(event, isDoubleClick)

        val centerX = width / 2
        var startY = 45
        val itemHeight = 28

        // Клик по области добавления
        if (mouseX in (centerX - 150).toDouble()..(centerX + 150).toDouble() &&
            mouseY in startY.toDouble()..(startY + 22).toDouble()) {
            if (isAdding) {
                advanceStage()
            } else {
                isAdding = true
                inputStage = 0
                newIcon = ""
                newCommand = ""
                newTooltip = ""
            }
            return true
        }

        startY += 32
        for ((index, btn) in buttons.withIndex()) {
            val y = startY + index * itemHeight
            if (y + itemHeight > height - 40) break

            val btnSize = 16
            // Вверх
            if (index > 0) {
                val upX = centerX + 100
                if (isHover(mouseX, mouseY, upX, y + 4, btnSize, btnSize)) {
                    moveButton(index, -1)
                    return true
                }
            }
            // Вниз
            if (index < buttons.size - 1) {
                val downX = centerX + 118
                if (isHover(mouseX, mouseY, downX, y + 4, btnSize, btnSize)) {
                    moveButton(index, 1)
                    return true
                }
            }
            // Удалить
            val delX = centerX + 136
            if (isHover(mouseX, mouseY, delX, y + 4, btnSize, btnSize)) {
                removeButton(index)
                return true
            }
        }

        return super.mouseClicked(event, isDoubleClick)
    }

    private fun advanceStage() {
        when (inputStage) {
            0 -> {
                if (newIcon.isNotBlank()) inputStage = 1
            }
            1 -> {
                if (newCommand.isNotBlank()) inputStage = 2
            }
            2 -> {
                if (buttons.size < InventoryButton.MAX_TABS) {
                    val nextIndex = (buttons.maxOfOrNull { it.index } ?: -1) + 1
                    val newBtn = InventoryButton(nextIndex, newIcon.trim(), newCommand.trim(), newTooltip.trim())
                    val list = buttons.toMutableList()
                    list.add(newBtn)
                    InventoryButtonsManager.setButtons(list)
                }
                isAdding = false
                inputStage = 0
                newIcon = ""
                newCommand = ""
                newTooltip = ""
            }
        }
    }

    private fun moveButton(index: Int, direction: Int) {
        val list = buttons.toMutableList()
        val target = index + direction
        if (target < 0 || target >= list.size) return
        val temp = list[index]
        list[index] = list[target]
        list[target] = temp
        list.forEachIndexed { i, b -> b.index = i }
        InventoryButtonsManager.setButtons(list)
    }

    private fun removeButton(index: Int) {
        val list = buttons.toMutableList()
        if (index in list.indices) {
            list.removeAt(index)
            list.forEachIndexed { i, b -> b.index = i }
            InventoryButtonsManager.setButtons(list)
        }
    }

    override fun keyPressed(event: KeyEvent): Boolean {
        val keyCode = event.input()

        if (isAdding) {
            if (keyCode == GLFW.GLFW_KEY_ENTER || keyCode == GLFW.GLFW_KEY_KP_ENTER) {
                advanceStage()
                return true
            }
            if (keyCode == GLFW.GLFW_KEY_ESCAPE) {
                isAdding = false
                inputStage = 0
                newIcon = ""
                newCommand = ""
                newTooltip = ""
                return true
            }
            if (keyCode == GLFW.GLFW_KEY_BACKSPACE) {
                when (inputStage) {
                    0 -> if (newIcon.isNotEmpty()) newIcon = newIcon.dropLast(1)
                    1 -> if (newCommand.isNotEmpty()) newCommand = newCommand.dropLast(1)
                    2 -> if (newTooltip.isNotEmpty()) newTooltip = newTooltip.dropLast(1)
                }
                return true
            }
        }

        return super.keyPressed(event)
    }

    override fun charTyped(event: CharacterEvent): Boolean {
        if (isAdding) {
            val chr = event.codepoint().toChar()
            when (inputStage) {
                0 -> if (newIcon.length < 40) newIcon += chr
                1 -> if (newCommand.length < 60) newCommand += chr
                2 -> if (newTooltip.length < 40) newTooltip += chr
            }
            return true
        }
        return super.charTyped(event)
    }

    override fun renderBackground(guiGraphics: GuiGraphics, mouseX: Int, mouseY: Int, delta: Float) {
        guiGraphics.fill(0, 0, width, height, 0x80000000.toInt())
    }

    override fun onClose() {
        InventoryButtonsManager.save()
        if (parent != null) {
            minecraft?.setScreen(parent)
        } else {
            super.onClose()
        }
    }
