                else -> ""
            }
            val displayText = if (inputText.isEmpty()) "§8Введите..." else "§f$inputText§b_"
            guiGraphics.drawString(font, stageName + displayText, centerX - 120, addY + 8, -1)
            guiGraphics.drawString(font, "§a[OK]", centerX + 100, addY + 8, -1)
        } else {
            guiGraphics.drawCenteredString(font, "§a+ Добавить кнопку", centerX, addY + 8, -1)
        }

        // Заголовок списка
        startY += 40
        guiGraphics.drawCenteredString(font, "§7Иконка          Команда          Подсказка", width / 2, startY - 15, 0xFFAAAAAA.toInt())

        // Список кнопок
        for ((index, btn) in buttons.withIndex()) {
            val y = startY + index * itemHeight
            if (y + itemHeight > height - 40) break

            guiGraphics.fill(centerX - 130, y, centerX + 130, y + 25, 0x70000000)

            val iconDisplay = btn.icon?.take(12) ?: "§8-"
            val cmdDisplay = (btn.command ?: "").take(15).let { if (it.length == 15 && (btn.command?.length ?: 0) > 15) "$it..." else it }
            val tipDisplay = (btn.tooltip ?: "").take(12).let { if (it.length == 12 && (btn.tooltip?.length ?: 0) > 12) "$it..." else it }

            guiGraphics.drawString(font, "§e$iconDisplay", centerX - 120, y + 8, -1)
            guiGraphics.drawString(font, "§f$cmdDisplay", centerX - 40, y + 8, -1)
            guiGraphics.drawString(font, "§8$tipDisplay", centerX + 30, y + 8, -1)

            // Кнопка удаления
            if (mouseX.toDouble() in (centerX + 110).toDouble()..(centerX + 125).toDouble() &&
                mouseY.toDouble() in y.toDouble()..(y + 25).toDouble()) {
                guiGraphics.drawString(font, "§cX", centerX + 115, y + 8, -1)
