        var startY = 40
        val itemHeight = 30

        if (button == 0) {
            // Клик по полю добавления
            if (mouseX in (centerX - 130).toDouble()..(centerX + 130).toDouble() &&
                mouseY in startY.toDouble()..(startY + 25).toDouble()) {
                if (isAdding) {
                    advanceStage()
                } else {
                    isAdding = true
                    inputStage = 0
                    newIcon = ""
                    newCommand = ""
                    newTooltip = ""
                }
